      (run.head_repository?.id === pr.head.repo.id && run.head_branch === pr.head.ref)));
  runs.sort((a, b) => b.id - a.id);
  if (!runs.length) throw new Error('No trusted PR metadata run exists for this revision');
  // Let an already-finishing gate consume the new comment or finish before rerun.
  await wait(5000);
  const {data: latest} = await github.rest.actions.getWorkflowRun({...repo, run_id: runs[0].id});
  if (latest.status !== 'completed') {
    core.info('The trusted review is still running and will read the current intent confirmation.');
    return;
  }
  await github.request('POST /repos/{owner}/{repo}/actions/runs/{run_id}/rerun', {...repo, run_id: runs[0].id});
  core.info('Requested a trusted PR metadata reassessment. Contributor tests are not rerun.');
}

async function purposeConfirmation(github, repo, pr, comments) {
  const comment = [...comments].reverse().find(item =>
    item.user?.type === 'User' && item.user.login === MANUAL_REVIEWER &&
    Number.isSafeInteger(item.id) && item.id > 0 &&
    intentText(item.body, pr.head.sha));
  if (!comment) return null;
  const {data} = await github.rest.repos.getCollaboratorPermissionLevel({...repo, username: comment.user.login});
  if (!['admin', 'maintain', 'write'].includes(data.permission)) return null;
  return {repository: `${repo.owner}/${repo.repo}`, number: pr.number, head_sha: pr.head.sha,
    actor: comment.user.login, permission: data.permission, comment_id: comment.id, ...intentText(comment.body, pr.head.sha)};
}

async function maintainerConfirmed(github, repo, pr, {reviewOnly = false} = {}) {
  const canConfirm = async user => {
    if (!user || user.type !== 'User') return false;
    const {data} = await github.rest.repos.getCollaboratorPermissionLevel({...repo, username: user.login});
    return ['admin', 'maintain', 'write'].includes(data.permission);
  };
  const reviews = await github.paginate(github.rest.pulls.listReviews, {...repo, pull_number: pr.number, per_page: 100});
  const latest = new Map();
  for (const review of reviews) {
    if (review.state !== 'COMMENTED' && review.state !== 'PENDING') latest.set(review.user?.login, review);
  }
  for (const review of latest.values()) {
    if (review.state === 'APPROVED' && review.commit_id === pr.head.sha && await canConfirm(review.user)) return true;
  }
  if (reviewOnly) return false;
  const comments = await github.paginate(github.rest.issues.listComments, {...repo, issue_number: pr.number, per_page: 100});
  for (const comment of comments) {
    if (intentText(comment.body, pr.head.sha) && await canConfirm(comment.user)) return true;
  }
  return false;
}

async function technicalRun(github, repo, pr, {receipt = false} = {}) {
  const {data} = await github.rest.actions.listWorkflowRuns({...repo, workflow_id: WORKFLOW,
    event: 'pull_request', head_sha: pr.head.sha, per_page: 100});
  const runs = data.workflow_runs.filter(run => run.head_sha === pr.head.sha &&
    (run.pull_requests.some(pull => pull.number === pr.number) ||
      (run.head_repository?.id === pr.head.repo.id && run.head_branch === pr.head.ref)));
  runs.sort((a, b) => b.id - a.id);
  const run = runs[0];
  if (!run || run.status !== 'completed') return {pending: true};
  if (run.conclusion !== 'success') return {failure: `PR verification concluded ${run.conclusion}`};
  const jobs = await github.paginate(github.rest.actions.listJobsForWorkflowRun,
    {...repo, run_id: run.id, filter: 'latest', per_page: 100});
  const verify = jobs.find(job => job.name === config.verification.job);
  if (!verify || verify.conclusion !== 'success' || VERIFY_STEPS.some(name =>
    !verify.steps.some(step => step.name === name && step.conclusion === 'success'))) {
    return {failure: 'Required verification steps did not all succeed'};
  }
  return receipt ? {url: run.html_url, run_id: run.id, attempt: run.run_attempt,
    head_sha: run.head_sha, event: run.event, conclusion: run.conclusion,
    job: {id: verify.id, name: verify.name, conclusion: verify.conclusion,
      steps: verify.steps.map(step => ({name: step.name, conclusion: step.conclusion}))}} : {url: run.html_url};
}

async function assertProtection(github, repo, policyJob = CHECK) {
  // Ruleset inspection needs metadata read, not an administrative credential.
  const {data: rules} = await github.request('GET /repos/{owner}/{repo}/rules/branches/{branch}',
    {...repo, branch: config.base_branch, per_page: 100});
  const checks = rules.find(rule => rule.type === 'required_status_checks')?.parameters;
  const reviews = rules.find(rule => rule.type === 'pull_request')?.parameters;
  if (!checks?.strict_required_status_checks_policy ||
    [config.verification.job, policyJob].some(name => !checks.required_status_checks.some(check =>
      check.context === name && check.integration_id === 15368)) ||
    !reviews || reviews.required_approving_review_count < 1 ||
    !reviews.dismiss_stale_reviews_on_push || !reviews.require_last_push_approval ||
    !rules.some(rule => rule.type === 'deletion') || !rules.some(rule => rule.type === 'non_fast_forward')) {
    throw new Error(`Main must enforce ${config.verification.job}, ${policyJob}, fresh approval, up-to-date checks, and protection from deletion/force pushes`);
  }
}

function matchesPath(filename, paths) {
  return paths.some(path => path.endsWith('/') ? filename.startsWith(path) : filename === path);
}

function needsDeployment(files) {
  return config.deployment !== null && files.some(file =>
    matchesPath(file.filename, config.deployment.paths) || matchesPath(file.previous_filename || '', config.deployment.paths));
}

async function gate({github, context, core, assessment = JSON.parse(process.env.ASSESSMENT),
  wait = sleep, maxPolls = 180, mergePolls = 30, nativeGate = false, verifyAcceptance = null}) {
  const repo = context.repo;
  const pull_number = numberFor(context);
  const getPr = async () => (await github.rest.pulls.get({...repo, pull_number})).data;
  let pr = await getPr();
  if (pr.state !== 'open' || pr.draft || pr.base.ref !== config.base_branch) {
    core.info('PR is not ready for the protected base branch; no review or merge action is needed.');
    return;
  }
  if (assessment.number !== pull_number || assessment.head_sha !== pr.head.sha || assessment.base_sha !== pr.base.sha) {
    throw new Error('Stale intent assessment: reassess the current PR revision');
  }
  if (context.eventName === 'issue_comment') {
    if (context.payload.comment.body.trim() !== `/approve-intent ${pr.head.sha}`) throw new Error('Stale or malformed intent confirmation');
    const {data} = await github.rest.repos.getCollaboratorPermissionLevel({...repo, username: context.payload.comment.user.login});
    if (context.payload.comment.user.type !== 'User' || !['admin', 'maintain', 'write'].includes(data.permission)) {
      throw new Error('Only a maintainer can confirm repository intent');
    }
  }
  const protection = () => require('./merge-protection.cjs').assertMergeProtection({github, repo,
    baseBranch: config.base_branch, manual: manualMerge, privateOwnerAutomatic,
    assertProtection: () => assertProtection(github, repo, nativeGate ? 'approve-and-merge' : CHECK)});
  const initialProtection = await protection();
  const controllerManaged = initialProtection.controllerManaged === true;
  if (controllerManaged && typeof verifyAcceptance !== 'function') throw new Error('Private owner merge requires a validated protocol-two acceptance record');
  // The native job is the required check. Additional GITHUB_TOKEN API checks
  // can attach to another run's suite; publish detail in this job's summary.
  const check = nativeGate ? null : (await github.rest.checks.create({...repo, name: CHECK, head_sha: pr.head.sha,
    status: 'in_progress', external_id: `clouseau:${pull_number}:${pr.head.sha}`,
    details_url: `https://github.com/${repo.owner}/${repo.repo}/actions/runs/${context.runId}`})).data;
  const finish = async (conclusion, summary) => {
    if (nativeGate) await core.summary.addRaw(`## Clouseau review: ${conclusion}\n\n${summary}\n`).write();
    else await github.rest.checks.update({...repo, check_run_id: check.id,
      status: 'completed', conclusion, output: {title: 'Clouseau approval policy', summary}});
  };

  try {
    const files = await github.paginate(github.rest.pulls.listFiles, {...repo, pull_number, per_page: 100});
    const codeowners = require('./codeowners.cjs');
    let ownership = codeownersRequired ? await codeowners.authority({github, repo, pr, files}) : {automatic: true};
    if (ownership.configured === false) {
      core.info(ownership.reason);
      if (privateOwnerAutomatic) ownership = {...ownership, automatic: false, reason: 'Explicit automatic mode requires configured CODEOWNERS on the accepted base; automatic merge is denied.'};
    }
    const automatic = ownership.automatic && !manualMerge;
    const nativeAutomatic = automatic && !controllerManaged;
    if (!nativeAutomatic && pr.auto_merge) {
      await github.graphql(`mutation($id:ID!) { disablePullRequestAutoMerge(input:{pullRequestId:$id}) { pullRequest { id } } }`, {id: pr.node_id});
    }
    if (nativeAutomatic && !pr.auto_merge) {
      await github.graphql(`mutation($id:ID!) { enablePullRequestAutoMerge(input:{pullRequestId:$id,mergeMethod:SQUASH}) {
        pullRequest { autoMergeRequest { enabledAt } }
      } }`, {id: pr.node_id});
    }
    pr = await getPr();
    if (pr.head.sha !== assessment.head_sha || pr.base.sha !== assessment.base_sha || nativeAutomatic && !pr.auto_merge) throw new Error('Auto-merge was not enabled on the assessed revision');
    if (!nativeAutomatic && pr.auto_merge) throw new Error('Automatic merge remains enabled for a PR that requires manual merge');
    const selfAuthored = pr.user?.login === 'github-actions[bot]';
    if (assessment.decision === 'blocked_technical' || assessment.decision === 'blocked_integrity') throw new Error(assessment.reason);
    const intentPending = assessment.decision === 'pending_technical';
    if (nativeGate && intentPending) throw new Error('AI assessment must finish after successful verification before the native policy job can pass');
    const humanRequired = selfAuthored || (!intentPending && assessment.decision !== 'auto_approve') || Boolean(scopeReason(files, pr));
    if (humanRequired && !await maintainerConfirmed(github, repo, pr, {reviewOnly: selfAuthored})) {
      if (!pr.assignees?.some(user => user.login === MANUAL_REVIEWER)) {
        await github.rest.issues.addAssignees({...repo, issue_number: pull_number, assignees: [MANUAL_REVIEWER]});
      }
      // GitHub cannot request a review from the PR's own author; assignment
      // still routes that intent decision to the repository owner.
      if (pr.user?.login !== MANUAL_REVIEWER && !pr.requested_reviewers?.some(user => user.login === MANUAL_REVIEWER)) {
        await github.rest.pulls.requestReviewers({...repo, pull_number, reviewers: [MANUAL_REVIEWER]});
      }
      const marker = `<!-- clouseau-intent:${pr.head.sha} -->`;
      const reason = assessment.reason.replaceAll('@', '').slice(0, 2000);
      const selfReview = selfAuthored ? 'This PR was authored by the approval bot. A maintainer must first submit an approving review on this exact revision; the bot cannot approve its own PR.\n\n' : '';
      const summary = `A maintainer's second opinion is required.\n\n${selfReview}${reason}\n\n` +
        `To confirm this change belongs in this repository, comment:\n\n\`/approve-intent ${pr.head.sha}\`\n\n` +
        'This confirms intent only. All tests and exact 100% line and branch coverage remain mandatory.';
      await finish('action_required', summary);
      const comments = await github.paginate(github.rest.issues.listComments, {...repo, issue_number: pull_number, per_page: 100});
      if (!comments.some(comment => comment.user.type === 'Bot' && comment.body.includes(marker))) {
        await github.rest.issues.createComment({...repo, issue_number: pull_number, body: `${marker}\n${summary}`});
      }
      core.info(automatic ? 'Auto-merge is armed; waiting for a maintainer intent confirmation.' : 'Automatic merge is disabled; waiting for a maintainer intent confirmation.');
      if (nativeGate) throw new Error('A maintainer intent confirmation is required');
      return;
    }
    let technical;
    for (let attempt = 0; attempt < maxPolls; attempt++) {
      pr = await getPr();
      if (pr.state !== 'open' || pr.draft || pr.head.sha !== assessment.head_sha || pr.base.sha !== assessment.base_sha) {
        throw new Error('PR changed while verification was running');
      }
      technical = await technicalRun(github, repo, pr);
      if (!technical.pending) break;
      await wait(15000);
    }
    if (!technical || technical.pending) throw new Error('Verification is pending; authorize fork CI or rerun this controller after CI completes');
    if (technical.failure) throw new Error(technical.failure);
    // Revalidate intent, head and base immediately before granting approval.
    pr = await getPr();
    if (pr.head.sha !== assessment.head_sha || pr.base.sha !== assessment.base_sha || pr.state !== 'open' || pr.draft) {
      throw new Error('PR changed before approval');
    }
    if (intentPending) {
      // A new run gives the read-only assessment job its own provider credential.
      // The write-capable controller never receives that credential.
      await github.rest.actions.createWorkflowDispatch({...repo, workflow_id: WORKFLOW, ref: config.base_branch,
        inputs: {pull_request: String(pull_number)}});
      core.info('Technical gate passed; requested intent assessment. No approval has been granted.');
      return;
    }
    if (humanRequired && !await maintainerConfirmed(github, repo, pr, {reviewOnly: selfAuthored})) throw new Error('Maintainer confirmation was withdrawn');
    const currentProtection = manualMerge || controllerManaged ? await protection() : null;
    if (manualMerge && ownership.automatic && codeownersRequired &&
        !(await codeowners.authority({github, repo, pr, files})).automatic) throw new Error('Code ownership changed before manual-mode approval');
    if (!selfAuthored) {
      await github.rest.pulls.createReview({...repo, pull_number, commit_id: pr.head.sha, event: 'APPROVE',
        body: `All tests and exact 100% line and branch coverage passed: ${technical.url}\n\n` +
          (humanRequired ? 'Repository intent confirmed by a maintainer.' : `Repository fit and supported intent assessed: ${assessment.reason}`)});
    }
    if (!ownership.automatic) {
      if (!await codeowners.approved({github, repo, pr, ownership})) {
        await finish('action_required', ownership.reason);
        core.info(ownership.reason);
        if (nativeGate) throw new Error('A current-head code-owner approval is required; automatic merge is disabled');
        return;
      }
      await finish('success', 'Tests, exact coverage and code-owner approval passed. Automatic merge remains disabled; a code owner must merge manually.' +
        (currentProtection && !currentProtection.enforced ? `\n\n${currentProtection.reason}` : ''));
      return;
    }
    if (manualMerge) {
      await finish('success', 'Tests, exact coverage and review passed. Automatic merge is disabled; the code owner must merge manually.' +
        (currentProtection.enforced ? '' : `\n\n${currentProtection.reason}`));
      return;
    }
    if (controllerManaged) {
      if (!currentProtection.controllerManaged) throw new Error('Private-plan acceptance mode changed before approval');
      pr = await require('./private-owner-merge.cjs').finalizePrivateOwner({github, repo, pr, assessment,
        baseBranch: config.base_branch, verify: async () => {
          await verifyAcceptance();
          const current = await protection();
          if (!current.controllerManaged) throw new Error('Private-plan acceptance mode changed before merge');
          if (humanRequired && !await maintainerConfirmed(github, repo, pr, {reviewOnly: selfAuthored})) throw new Error('Maintainer confirmation was withdrawn');
        }});
      await finish('success', `Tests, exact coverage, validated acceptance and fresh approval passed. Controller-enforced owner merge completed: ${pr.merge_commit_sha}. Native branch protection is unavailable.`);
      if (!nativeGate) await finalize({github, context, core, assessment, wait, mergePolls, pr, files});
      return;
    }
    // Ownership is read again at the write boundary, including current team membership.
    if (codeownersRequired && !((value) => value.automatic && (!privateOwnerAutomatic || value.configured !== false))(await codeowners.authority({github, repo, pr, files}))) throw new Error('Code ownership changed before automatic approval');
    await finish('success', `All required tests and coverage passed. Intent ${humanRequired ? 'confirmed by a maintainer' : 'supported by repository fit and evidence'}.\n\n${technical.url}`);

    if (!nativeGate) await finalize({github, context, core, assessment, wait, mergePolls, pr, files});
  } catch (error) {
    await finish('failure', error.message);
    throw error;
  }
}

async function finalize({github, context, core, assessment = JSON.parse(process.env.ASSESSMENT),
  wait = sleep, mergePolls = 75, pr, files}) {
  const repo = context.repo;
  const pull_number = numberFor(context);
  const getPr = async () => (await github.rest.pulls.get({...repo, pull_number})).data;
  if (!pr) pr = await getPr();
  if (assessment.number !== pull_number || pr.head.sha !== assessment.head_sha || pr.base.ref !== config.base_branch) {
    throw new Error('PR changed before merge finalization');
  }
  if (manualMerge) {
    if (pr.auto_merge) await github.graphql(`mutation($id:ID!) { disablePullRequestAutoMerge(input:{pullRequestId:$id}) { pullRequest { id } } }`, {id: pr.node_id});
    core.info('Manual merge mode never arms auto-merge or dispatches deployment. A code owner must merge manually.');
    return;
  }
  if (privateOwnerAutomatic && !pr.merged) {
    const checked = await require('./merge-protection.cjs').assertMergeProtection({github, repo,
      baseBranch: config.base_branch, manual: false, privateOwnerAutomatic,
      assertProtection: () => assertProtection(github, repo, 'approve-and-merge')});
    if (checked.controllerManaged) throw new Error('Private owner merge must complete through the validated acceptance gate before finalization');
  }
  if (codeownersRequired && !pr.merged) {
    if (!files) files = await github.paginate(github.rest.pulls.listFiles, {...repo, pull_number, per_page: 100});
    const ownership = await require('./codeowners.cjs').authority({github, repo, pr, files});
    if (!ownership.automatic || privateOwnerAutomatic && ownership.configured === false) {
      core.info('Code-owner-authored PRs alone qualify for automatic merge; this PR requires manual code-owner merge.');
      return;
    }
  }
  for (let attempt = 0; attempt < mergePolls; attempt++) {
    pr = await getPr();
    if (pr.merged) break;
    if (pr.head.sha !== assessment.head_sha || !pr.auto_merge) throw new Error('Auto-merge was disabled or the PR changed');
    await wait(4000);
  }
  if (!pr.merged) {
    core.info('Approval and auto-merge are enabled; GitHub is waiting for branch requirements.');
    return;
  }
  // GITHUB_TOKEN merges suppress push workflows; explicitly preserve CD.
  if (!files) files = await github.paginate(github.rest.pulls.listFiles, {...repo, pull_number, per_page: 100});
  if (needsDeployment(files)) {
    const {data: main} = await github.rest.repos.getBranch({...repo, branch: config.base_branch});
    if (main.commit.sha !== pr.merge_commit_sha) {
      throw new Error('Main advanced before CD dispatch: verify deployment of the latest main revision');
    }
    const {data: deployments} = await github.rest.actions.listWorkflowRuns({...repo,
      workflow_id: config.deployment.workflow, head_sha: pr.merge_commit_sha, per_page: 100});
    if (!deployments.workflow_runs.some(run => ['push', 'workflow_dispatch'].includes(run.event))) {
      await github.rest.actions.createWorkflowDispatch({...repo, workflow_id: config.deployment.workflow, ref: config.base_branch});
    }
    core.info(`Merged ${pr.merge_commit_sha}; deployment workflow requested. Deployment health is a separate result.`);
  }
}

return {assess, assessWhenReady, requestReassessment, gate, finalize, scopeReason, assessmentResult, purposeConfirmation, maintainerConfirmed, technicalRun, assertProtection, needsDeployment, VERIFY_STEPS, REVIEW_CONTROL_REASON};

}

module.exports = {createPolicy, intentText};

'use strict';

const fs = require('node:fs');
const path = require('node:path');
const {digest, validateReport} = require('./acceptance.cjs');
const {collectSnapshot, refresh} = require('./acceptance-sources.cjs');
const {reviewChange, combine, validateInspection} = require('./acceptance-review.cjs');
const {priorState, reconcile, publication} = require('./acceptance-ledger.cjs');

const RECORD = 'work/clouseau-acceptance.json';
const policyDigest = () => digest(fs.readFileSync(path.join(__dirname, '../policy/change-acceptance.md'), 'utf8'));

function numberFor(context) {
  const value = context.payload.pull_request?.number || (context.payload.issue?.pull_request && context.payload.issue.number) || process.env.PR_NUMBER;
  if (!/^[1-9][0-9]*$/.test(String(value))) throw new Error('A PR number is required');
  return Number(value);
}

function decided(result, controls) {
  return controls && result.decision === 'auto_approve' ? 'owner_decision' : result.decision;
}

function verifyRecord(record, assessment, config, engine = null) {
  if (engine && (digest(record.engine) !== digest(engine) || digest(assessment.engine) !== digest(engine))) {
    throw new Error('Acceptance record belongs to a different frozen engine');
  }
  if (record.local_receipt) {
    require('./local-receipt.cjs').verifyReceipt(record.local_receipt, {
      engine, trust: config.local_review, repository: record.snapshot.repository, author: record.local_author,
      headSha: assessment.head_sha, baseSha: assessment.base_sha,
      configDigest: digest(config), policyDigest: policyDigest(),
    });
    for (const field of ['snapshot', 'result', 'controls']) {
      if (digest(record[field]) !== digest(record.local_receipt.payload.record[field])) throw new Error('Local review record was substituted');
    }
    if (digest(record.previous.findings) !== digest(record.local_receipt.payload.record.previous.findings)) throw new Error('Local review history was substituted');
  }
  if (assessment.version !== 2 || digest(record) !== assessment.record_digest ||
      record.snapshot.config_digest !== digest(config) || record.snapshot.policy_digest !== policyDigest() ||
      record.snapshot.head_sha !== assessment.head_sha || record.snapshot.base_sha !== assessment.base_sha ||
      (!record.local_receipt && record.snapshot.number !== assessment.number) || record.snapshot.digest !== refresh(structuredClone(record.snapshot)).digest) {
    throw new Error('Stale or altered acceptance record');
  }
  const reviews = record.result.reviews;
  if (reviews.length !== 2 || reviews.map(item => item.role).join(',') !== 'examiner,challenger') throw new Error('Both independent acceptance reviews are required');
  for (const review of reviews) {
    const view = validateInspection(review.report, record.snapshot, review.drafts);
    review.scores = validateReport(review.report, view);
  }
  record.result.decision = combine(reviews);
  const state = reconcile(record.result, record.snapshot, record.previous.findings);
  if (state.unresolved.length && ['auto_approve', 'owner_decision'].includes(record.result.decision)) record.result.decision = 'review_incomplete';
  if (assessment.decision !== decided(record.result, record.controls || Boolean(record.local_authorization))) throw new Error('Acceptance decision differs from the deterministic record');
  return {state, ...publication({...record.result, decision: assessment.decision},
    {...record.snapshot, number: assessment.number}, state)};
}

function createAcceptancePolicy(config, legacy, engine = null) {
  if (config.local_review?.central_source && !require('./central-version.cjs').acceptsEngine(config.local_review, engine)) {
    throw new Error('Protected central-source integration requires this run frozen engine identity');
  }
  async function assess({github, context, fetchImpl, retryWait, report, recordPath = RECORD, receiptOnly = false}) {
    const repo = context.repo;
    const number = numberFor(context);
    const {data: pr} = await github.rest.pulls.get({...repo, pull_number: number});
    const identity = {version: 2, number, head_sha: pr.head.sha, base_sha: pr.base.sha, ...(engine ? {engine} : {})};
    if (pr.state !== 'open' || pr.draft || pr.base.ref !== config.base_branch) return {...identity, decision: 'not_ready', reason: 'PR is not ready for the protected base branch'};
    const technical = await legacy.technicalRun(github, repo, pr, {receipt: true});
    const technicalBlock = technical.pending ? {decision: 'pending_technical', reason: 'Waiting for all tests and exact 100% coverage'} :
      technical.failure ? {decision: 'blocked_technical', reason: technical.failure} : null;
    const observations = [];
    const snapshots = {};
    let snapshot;
    fs.mkdirSync(path.dirname(recordPath), {recursive: true});
    const diagnostic = value => {
      if (snapshot) snapshots[snapshot.digest] ??= structuredClone(snapshot);
      fs.writeFileSync(`${recordPath}.diagnostic.json`, JSON.stringify({...value, snapshots}, null, 2) + '\n');
    };
    try {
      const receipts = require('./local-receipt.cjs');
      const receiptRef = receipts.marker(pr.body);
      // A signed local quality review is reusable even when independent CI
      // cannot yet authorize acceptance. Unstamped changes retain the existing
      // technical precondition before any paid investigation.
      if (!receiptRef && technicalBlock) return {...identity, ...technicalBlock};
      const files = await github.paginate(github.rest.pulls.listFiles, {...repo, pull_number: number, per_page: 100});
      const comments = await github.paginate(github.rest.issues.listComments, {...repo, issue_number: number, per_page: 100});
      const previous = priorState(comments, `${repo.owner}/${repo.repo}`, number);
      if (receiptRef) {
        const bundle = await receipts.loadReceipt({github, repo, ref: receiptRef});
        const verified = receipts.verifyReceipt(bundle, {engine, trust: config.local_review,
          repository: `${repo.owner}/${repo.repo}`, author: pr.user.login, headSha: pr.head.sha, baseSha: pr.base.sha,
          configDigest: digest(config), policyDigest: policyDigest()});
        await receipts.verifySources({github, repo, pr, snapshot: verified.record.snapshot, config, files, reviewerSha: bundle.payload.reviewer_sha});
        const controls = legacy.scopeReason(files, pr);
        const authorization = controls === legacy.REVIEW_CONTROL_REASON ? await legacy.purposeConfirmation(github, repo, pr, comments) : null;
        if (digest(previous.findings) !== digest(verified.record.previous.findings) || controls && !authorization) {
          throw new Error('Local receipt cannot replace changed review history or protected-control authorization');
        }
        if (technicalBlock) {
          if (report) report('Authenticated local Clouseau quality review verified. Independent CI acceptance remains blocked. CI AI calls: 0.');
          return {...identity, ...technicalBlock, review_source: 'authenticated_local', provider_api_calls: 0,
            reason: `Authenticated local quality review verified without an AI rerun; independent CI acceptance remains blocked: ${technicalBlock.reason}`};
        }
        const record = {...verified.record, ...(engine ? {engine} : {}), ...(authorization ? {local_authorization: authorization} : {}), previous, technical, local_author: pr.user.login,
          local_artifact: receiptRef, local_receipt: bundle};
        fs.writeFileSync(recordPath, JSON.stringify(record, null, 2) + '\n');
        if (report) report('Authenticated local Clouseau review verified. CI AI calls: 0.');
        return {...identity, decision: authorization ? 'owner_decision' : 'auto_approve', record_digest: digest(record),
          review_source: 'authenticated_local', provider_api_calls: 0,
          reason: 'Authenticated passing local review; source, scores and CI verification validated without an AI rerun.'};
      }
      if (receiptOnly || config.local_review?.mode === 'required') {
        return {...identity, decision: 'review_incomplete', reason: 'This repository requires an authenticated local Clouseau review receipt.'};
      }
      const intentConfirmation = await legacy.purposeConfirmation(github, repo, pr, comments);
      snapshot = await collectSnapshot({github, repo, pr, files, config, technical, intentConfirmation});
      snapshot.prior_findings = previous.findings;
      const repair = require('./acceptance-repair.cjs');
      const reservations = repair.history(comments, snapshot.repository, number);
      snapshot.repair_history = reservations;
      refresh(snapshot);
      const result = await reviewChange({github, repo, snapshot, config: config.acceptance, fetchImpl, wait: retryWait, log: report,
        observe: observation => {observations.push(observation); diagnostic({identity, observations});}});
      const state = reconcile(result, snapshot, previous.findings);
      if (state.unresolved.length && ['auto_approve', 'owner_decision'].includes(result.decision)) result.decision = 'review_incomplete';
      const controls = legacy.scopeReason(files, pr);
      const decision = decided(result, Boolean(controls));
      const record = {version: 2, ...(engine ? {engine} : {}), snapshot, result, previous, controls: Boolean(controls), technical};
      // Retain the complete record. Never place the large, model-controlled
      // ledger in workflow outputs or interpolate it into shell commands.
      fs.writeFileSync(recordPath, JSON.stringify(record, null, 2) + '\n');
      publication({...result, decision}, snapshot, state);
      const assessment = {...identity, decision, record_digest: digest(record),
        reason: controls && decision === 'owner_decision' ? controls : `Evidence-bound product and technical acceptance: ${decision}.`};
      if (!record.controls && ['repair_required', 'blocked_integrity'].includes(result.decision)) {
        try {
          const proposal = await repair.propose({record, reservations, fetchImpl, wait: retryWait, log: report});
          fs.writeFileSync(`${recordPath}.repair.json`, JSON.stringify(proposal, null, 2) + '\n');
          assessment.repair_digest = digest(proposal);
        } catch (error) {diagnostic({identity, observations, repair_unavailable: error.message});}
      }
      return assessment;
    } catch (error) {
      diagnostic({identity, observations, failure: error.message, details: error.details || null});
      if (report) report(`Acceptance investigation stopped: ${error.message}`);
      const engineMismatch = error.message.startsWith('Invalid local review receipt: engine mismatch;');
      return {...identity, decision: 'review_incomplete',
        ...(engineMismatch ? {review_source: 'authenticated_local_rejected', provider_api_calls: 0} : {}),
        reason: engineMismatch ? error.message : 'Automated review evidence is incomplete; inspect the assessment diagnostic and repair the missing evidence.'};
    }
  }

  async function assessWhenReady({wait = ms => new Promise(resolve => setTimeout(resolve, ms)), maxPolls = 260, ...options}) {
    for (let attempt = 0; attempt < maxPolls; attempt++) {
      const result = await assess(options);
      if (result.decision !== 'pending_technical') return result;
      await wait(15000);
    }
    throw new Error('Verification did not finish before the assessment deadline');
  }

  async function gate({github, context, core, assessment = JSON.parse(process.env.ASSESSMENT), recordPath = RECORD, ...options}) {
    const hold = reason => legacy.gate({github, context, core, ...options,
      assessment: {...assessment, decision: 'blocked_technical', reason}});
    if (!assessment.record_digest) return hold(assessment.reason);
    const record = JSON.parse(fs.readFileSync(recordPath, 'utf8'));
    const {body, pages} = verifyRecord(record, assessment, config, engine);
    if (record.snapshot.repository !== `${context.repo.owner}/${context.repo.repo}`) throw new Error('Acceptance record belongs to a different repository');
    const {data: pr} = await github.rest.pulls.get({...context.repo, pull_number: numberFor(context)});
    if (record.local_receipt && record.local_author !== pr.user.login) throw new Error('Local receipt author changed');
    if (pr.head.sha !== assessment.head_sha || pr.base.sha !== assessment.base_sha) throw new Error('PR changed after acceptance investigation');
    const technical = await legacy.technicalRun(github, context.repo, pr, {receipt: true});
    if (digest(technical) !== digest(record.technical)) throw new Error('Verification changed after acceptance investigation');
    const comments = await github.paginate(github.rest.issues.listComments, {...context.repo, issue_number: pr.number, per_page: 100});
    if (record.snapshot.intent_confirmation && digest(record.snapshot.intent_confirmation) !==
        digest(await legacy.purposeConfirmation(github, context.repo, pr, comments))) {
      throw new Error('Accepted purpose confirmation changed; reassess the current evidence');
    }
    if (record.local_authorization && digest(record.local_authorization) !==
        digest(await legacy.purposeConfirmation(github, context.repo, pr, comments))) {
      throw new Error('Local review owner authorization changed; confirm this exact revision again');
    }
    const current = priorState(comments, record.snapshot.repository, pr.number);
    if (digest(current) !== digest(record.previous)) throw new Error('Acceptance history changed; reassess the current record');
    const links = [];
    for (const [index, page] of pages.entries()) {
      const marker = page.split('\n')[0];
      const existing = comments.find(item => item.user?.login === 'github-actions[bot]' && item.body.startsWith(`${marker}\n`));
      const response = existing ? await github.rest.issues.updateComment({...context.repo, comment_id: existing.id, body: page}) :
        await github.rest.issues.createComment({...context.repo, issue_number: pr.number, body: page});
      links.push(`[Evidence ${index + 1}/${pages.length}](https://github.com/${record.snapshot.repository}/pull/${pr.number}#issuecomment-${response.data.id})`);
    }
    let published = links.length ? `${body}\n\nComplete factor inputs and literal evidence: ${links.join(' · ')}` : body;
    if (record.local_receipt) published += `\n\nAuthenticated local review: ` +
      `[signed evidence](https://github.com/${record.snapshot.repository}/blob/${record.local_artifact}/clouseau-review.json). ` +
      'CI verified the signature, source, scores and passing tests/coverage. **CI AI review calls: 0.**';
    if (current.comment === null) await github.rest.issues.createComment({...context.repo, issue_number: pr.number, body: published});
    else await github.rest.issues.updateComment({...context.repo, comment_id: current.comment, body: published});
    await core.summary.addRaw(published).write();
    if (!['auto_approve', 'owner_decision'].includes(assessment.decision)) {
      return hold(`Clouseau ${assessment.decision}: automated investigation or an in-envelope repair is required. Owner confirmation cannot waive this result.`);
    }
    // Legacy native merge mechanics still enforce protection and current
    // technical checks. Only an explicit purpose/authority decision may use
    // the existing exact-revision owner confirmation path.
    return legacy.gate({github, context, core, ...options,
      // The private-plan path cannot delegate freshness to unavailable native
      // protection. Revalidate the exact record at its atomic write boundary.
      verifyAcceptance: async () => {
        const currentRecord = JSON.parse(fs.readFileSync(recordPath, 'utf8'));
        const latest = verifyRecord(currentRecord, assessment, config, engine);
        const {data: currentPr} = await github.rest.pulls.get({...context.repo, pull_number: pr.number});
        if (currentPr.head.sha !== assessment.head_sha || currentPr.base.sha !== assessment.base_sha ||
            currentRecord.local_receipt && currentRecord.local_author !== currentPr.user.login) throw new Error('Acceptance author or revision changed before private merge');
        if (currentRecord.local_receipt) {
          const currentFiles = await github.paginate(github.rest.pulls.listFiles,
            {...context.repo, pull_number: pr.number, per_page: 100});
          await require('./local-receipt.cjs').verifySources({github, repo: context.repo, pr: currentPr,
            snapshot: currentRecord.snapshot, config, files: currentFiles,
            reviewerSha: currentRecord.local_receipt.payload.reviewer_sha});
        }
        const currentTechnical = await legacy.technicalRun(github, context.repo, currentPr, {receipt: true});
        if (digest(currentTechnical) !== digest(currentRecord.technical)) throw new Error('Verification changed before private merge');
        const currentComments = await github.paginate(github.rest.issues.listComments,
          {...context.repo, issue_number: pr.number, per_page: 100});
        for (const authorization of [currentRecord.snapshot.intent_confirmation, currentRecord.local_authorization].filter(Boolean)) {
          if (digest(authorization) !== digest(await legacy.purposeConfirmation(github, context.repo, currentPr, currentComments))) {
            throw new Error('Exact recorded purpose authorization changed before private merge');
          }
        }
        if (digest(priorState(currentComments, currentRecord.snapshot.repository, pr.number).findings) !== digest(latest.state.findings)) {
          throw new Error('Acceptance findings changed before private merge');
        }
      },
      assessment: {...assessment, decision: assessment.decision === 'owner_decision' ? 'second_opinion' : 'auto_approve'}});
  }

  async function finalize({assessment = JSON.parse(process.env.ASSESSMENT), ...options}) {
    if (engine && digest(assessment.engine) !== digest(engine)) throw new Error('Merge assessment belongs to a different frozen engine');
    return legacy.finalize({...options, assessment});
  }

  return {...legacy, assess, assessWhenReady, gate, finalize};
}

module.exports = {RECORD, policyDigest, numberFor, decided, verifyRecord, createAcceptancePolicy};

'use strict';

const crypto = require('node:crypto');
const {digest, validateReport} = require('./acceptance.cjs');
const {refresh, safePath} = require('./acceptance-sources.cjs');
const {validateInspection, combine} = require('./acceptance-review.cjs');
const {engineDigest} = require('./local-version.cjs');
const {reconcile} = require('./acceptance-ledger.cjs');
const {centralSource, acceptsEngine} = require('./central-version.cjs');

const DOMAIN = 'clouseau.local-review.v1';
const MAX_RECEIPT_BYTES = 3000000;
const MARKER = /<!-- clouseau-local-review:v1 ([a-f0-9]{40}) -->/g;
const sha = value => typeof value === 'string' && /^[a-f0-9]{40}$/.test(value);
const fail = message => {throw new Error(`Invalid local review receipt: ${message}`);};
const requireReceipt = (value, message) => {if (!value) fail(message);};

function validateTrust(trust) {
  requireReceipt(trust && (centralSource(trust.central_source) && trust.reviewer_digest === undefined ||
    trust.central_source === undefined && /^[a-f0-9]{64}$/.test(trust.reviewer_digest)) && ['required', 'optional'].includes(trust.mode) &&
    Array.isArray(trust.keys) && trust.keys.length > 0 &&
    Number.isSafeInteger(trust.max_age_seconds) && trust.max_age_seconds > 0 &&
    trust.max_age_seconds <= 86400, 'explicit trust policy and maximum age required');
  const ids = new Set();
  for (const key of trust.keys) {
    requireReceipt(key && typeof key.id === 'string' && /^[a-zA-Z0-9_-]{1,80}$/.test(key.id) &&
      !ids.has(key.id) && typeof key.issuer === 'string' && key.issuer.length > 0 &&
      typeof key.github_actor === 'string' && /^[a-zA-Z0-9][a-zA-Z0-9-]{0,38}$/.test(key.github_actor) &&
      typeof key.public_key === 'string' && key.public_key.length < 1000 &&
      typeof key.revoked === 'boolean', 'invalid or repeated trusted issuer');
    const publicKey = crypto.createPublicKey(key.public_key);
    requireReceipt(publicKey.asymmetricKeyType === 'ed25519', 'Ed25519 public key required');
    ids.add(key.id);
  }
  return trust;
}

function reviewDecision(record) {
  const {snapshot, result} = record;
  requireReceipt(snapshot && result && snapshot.digest === refresh(structuredClone(snapshot)).digest,
    'altered evidence snapshot');
  requireReceipt(result.snapshot === snapshot.digest && result.policy_digest === snapshot.policy_digest &&
    result.config_digest === snapshot.config_digest, 'review does not match evidence');
  const graded = role => result.reviews?.find(item => item.role === role)?.report?.findings?.length > 0;
  requireReceipt(Array.isArray(result.usage) && result.usage.length >= 2 &&
    result.execution_digest === digest(result.usage) && new Set(result.usage.map(item => item.session)).size === result.usage.length &&
    result.usage.every(item => ['codex', 'claude', 'opencode'].includes(item.harness) && [undefined, 'agent_session'].includes(item.execution) &&
      typeof item.session === 'string' && item.session.length > 0 &&
      ['request_digest', 'response_digest', 'transport_digest'].every(name => /^[a-f0-9]{64}$/.test(item[name]))) &&
    // Grading runs only for findings, so a role without findings has no grading round to record.
    ['examiner', 'challenger'].every(role => ['investigation', 'grading'].every(phase =>
      (phase === 'grading' && !graded(role)) || result.usage.some(item => item.role === role && item.phase === phase))),
    'complete independent harness execution records required');
  requireReceipt(Array.isArray(result.reviews) && result.reviews.length === 2 &&
    result.reviews.map(item => item.role).join(',') === 'examiner,challenger', 'two independent roles required');
  const reviews = result.reviews.map(item => ({...item,
    scores: validateReport(item.report, validateInspection(item.report, snapshot, item.drafts))}));
  const prior = record.local_previous?.findings || [];
  requireReceipt(digest(snapshot.prior_findings) === digest(prior), 'local finding history differs from the reviewed evidence');
  const state = reconcile({...result, reviews}, snapshot, prior);
  const combined = combine(reviews);
  const decision = state.unresolved.length && combined === 'auto_approve' ? 'review_incomplete' : combined;
  requireReceipt(result.decision === decision, 'claimed decision differs from calculated decision');
  return {decision, reviews};
}

function issueReceipt({record, privateKey, keyId, issuer, reviewerSha, reviewerDigest = engineDigest(), now = Date.now(), lifetime = 3600,
  nonce = crypto.randomBytes(32).toString('hex')}) {
  requireReceipt(reviewDecision(record).decision === 'auto_approve', 'only a passing review can be signed');
  requireReceipt(sha(reviewerSha) && /^[a-f0-9]{64}$/.test(reviewerDigest) && /^[a-f0-9]{64}$/.test(nonce) && Number.isSafeInteger(lifetime) &&
    lifetime > 0 && lifetime <= 86400, 'invalid runner revision, challenge or lifetime');
  const key = crypto.createPrivateKey(privateKey);
  requireReceipt(key.asymmetricKeyType === 'ed25519', 'Ed25519 signing key required');
  const payload = {type: DOMAIN, key_id: keyId, issuer, reviewer_sha: reviewerSha, reviewer_digest: reviewerDigest,
    issued_at: Math.floor(now / 1000), expires_at: Math.floor(now / 1000) + lifetime,
    nonce, record_digest: digest(record), record};
  const signature = crypto.sign(null, Buffer.from(`${DOMAIN}\0${digest(payload)}`), key).toString('base64url');
  return {payload, signature};
}

function verifySignedRecord(bundle, {trust, repository, author, headSha, baseSha, reviewerSha, reviewerDigest = engineDigest(), configDigest, policyDigest,
  now = Date.now(), engine = null}) {
  validateTrust(trust);
  requireReceipt(bundle && Object.keys(bundle).sort().join(',') === 'payload,signature' &&
    typeof bundle.signature === 'string' && /^[a-zA-Z0-9_-]{86}$/.test(bundle.signature) &&
    Buffer.byteLength(JSON.stringify(bundle)) <= MAX_RECEIPT_BYTES, 'malformed signature envelope');
  const p = bundle.payload;
  requireReceipt(p && Object.keys(p).sort().join(',') ===
    'expires_at,issued_at,issuer,key_id,nonce,record,record_digest,reviewer_digest,reviewer_sha,type' && p.type === DOMAIN,
    'unknown receipt type or fields');
  const key = trust.keys.find(item => item.id === p.key_id && item.issuer === p.issuer && !item.revoked);
  requireReceipt(key && crypto.verify(null, Buffer.from(`${DOMAIN}\0${digest(p)}`), key.public_key,
    Buffer.from(bundle.signature, 'base64url')), 'untrusted, revoked or invalid signature');
  requireReceipt(key.github_actor === author, 'signing identity is not enrolled for this PR author');
  const timestamp = Math.floor(now / 1000);
  requireReceipt(Number.isSafeInteger(p.issued_at) && Number.isSafeInteger(p.expires_at) &&
    p.issued_at <= timestamp && p.expires_at > timestamp && p.expires_at > p.issued_at &&
    p.expires_at - p.issued_at <= trust.max_age_seconds && timestamp - p.issued_at <= trust.max_age_seconds &&
    typeof p.nonce === 'string' && /^[a-f0-9]{64}$/.test(p.nonce), 'expired, future or invalid challenge');
  if (trust.central_source || engine) {
    requireReceipt(acceptsEngine(trust, engine) && engine.digest === reviewerDigest &&
      p.reviewer_digest === engine.digest && p.reviewer_sha === engine.sha,
    'engine mismatch; refresh public Clouseau and review again, then start a fresh CI run. No paid fallback is allowed');
  }
  const record = p.record;
  const snapshot = record.snapshot;
  requireReceipt(p.record_digest === digest(record) && snapshot.repository === repository &&
    sha(headSha) && snapshot.head_sha === headSha && sha(baseSha) && snapshot.base_sha === baseSha &&
    sha(p.reviewer_sha) && (!reviewerSha || p.reviewer_sha === reviewerSha) &&
    p.reviewer_digest === reviewerDigest && (engine || trust.reviewer_digest === reviewerDigest) && snapshot.config_digest === configDigest &&
    snapshot.policy_digest === policyDigest, 'repository, revisions, policy, configuration or record changed');
  const result = reviewDecision(record);
  requireReceipt(result.decision === 'auto_approve', 'review did not pass');
  return {record, ...result};
}

function verifyReceipt(bundle, options) {
  const result = verifySignedRecord(bundle, options);
  const {snapshot} = result.record;
  requireReceipt(snapshot.intent_confirmation === null && snapshot.number === 0 &&
    Array.isArray(snapshot.prior_findings) && result.record.controls === false &&
    !Object.hasOwn(result.record, 'installation'), 'receipt cannot grant owner authority');
  return result;
}

function marker(body) {
  const text = body || '';
  requireReceipt(!text.includes('clouseau-installation-review:'), 'installation-only evidence cannot approve an ordinary PR');
  const matches = [...text.matchAll(MARKER)];
  requireReceipt(matches.length <= 1, 'multiple receipt references');
  requireReceipt([...text.matchAll(/clouseau-local-review:/g)].length === matches.length,
    'malformed or unsupported receipt reference; no paid fallback is allowed');
  return matches[0]?.[1] || null;
}

async function loadReceipt({github, repo, ref}) {
  requireReceipt(sha(ref), 'immutable receipt reference required');
  let {data} = await github.rest.repos.getContent({...repo, ref, path: 'clouseau-review.json'});
  if (data.encoding === 'none') {
    requireReceipt(data.type === 'file' && sha(data.sha) && Number.isSafeInteger(data.size) &&
      data.size >= 0 && data.size <= MAX_RECEIPT_BYTES, 'complete receipt artifact unavailable');
    const metadata = data;
    ({data} = await github.rest.git.getBlob({...repo, file_sha: metadata.sha}));
    requireReceipt(data.sha === metadata.sha && data.size === metadata.size,
      'receipt blob differs from immutable artifact');
    requireReceipt(data.encoding === 'base64' && typeof data.content === 'string', 'complete receipt blob unavailable');
    const bytes = Buffer.from(data.content, 'base64');
    requireReceipt(bytes.length === metadata.size && crypto.createHash('sha1')
      .update(`blob ${bytes.length}\0`).update(bytes).digest('hex') === metadata.sha,
    'receipt blob content differs from immutable artifact');
  }
  requireReceipt(data.encoding === 'base64' && typeof data.content === 'string' && data.size <= MAX_RECEIPT_BYTES,
    'complete receipt artifact unavailable');
  return JSON.parse(Buffer.from(data.content, 'base64').toString('utf8'));
}

async function verifySources({github, repo, pr, snapshot, config, files, reviewerSha, installation = null}) {
  requireReceipt(files.length === pr.changed_files && files.length > 0 &&
    digest(files.map(file => file.filename).sort()) === digest(snapshot.paths), 'changed-file inventory differs');
  requireReceipt(snapshot.files.length === files.length && files.every(file => snapshot.files.some(item =>
    item.path === file.filename && item.status === file.status)), 'changed-file status differs');
  requireReceipt(snapshot.tickets.length === 0 &&
    snapshot.intent_confirmation === null, 'unsupported mutable prior history or requirements');
  for (const filename of [config.readme, config.repository_policy]) {
    requireReceipt(Object.values(snapshot.sources).some(source => source.path === filename &&
      source.ref === (installation ? pr.head.sha : pr.base.sha) && source.authority === 'trusted' && source.kind === 'contract'),
    'protected purpose evidence omitted');
  }
  for (const [id, source] of Object.entries(snapshot.sources)) {
    if (id === 'installation-authorization') {
      requireReceipt(installation && source.authority === 'trusted' && source.kind === 'contract' &&
        source.path === `commits/${pr.head.sha}/comments/${installation.comment_id}` && source.ref === digest(installation) &&
        source.content === JSON.stringify(installation), 'installation authority was substituted');
      continue;
    }
    if (id === 'verification') {
      requireReceipt(source.authority === 'trusted' && source.kind === 'verification' && source.ref === pr.head.sha,
        'invalid local execution receipt');
      continue;
    }
    if (id === 'local-request') {
      requireReceipt(source.authority === 'untrusted' && source.kind === 'requirement' &&
        source.ref === digest(source.content), 'local request is not sealed untrusted evidence');
      continue;
    }
    if (source.path.startsWith('.clouseau-ci/')) {
      let reference;
      try {reference = require('./central-version.cjs').engineEvidence(source.path, reviewerSha);}
      catch {fail('invalid frozen engine evidence');}
      const {relative, ref} = reference;
      requireReceipt(source.ref === ref &&
        source.authority === 'untrusted' && source.kind === 'source', 'invalid frozen engine evidence');
      const root = require('node:path').join(__dirname, '..');
      // The action has already checked this source against the run digest.
      // Git-free distributions compare the same file bytes without invoking Git.
      let content;
      if (ref === reviewerSha) content = require('node:fs').readFileSync(require('node:path').join(root, relative), 'utf8');
      else {
        const {data} = await github.rest.repos.getContent({owner: 'gaulatti', repo: 'clouseau', ref, path: relative});
        requireReceipt(data.encoding === 'base64' && typeof data.content === 'string' && data.size <= 300000, 'historical engine evidence unavailable');
        content = new TextDecoder('utf-8', {fatal: true}).decode(Buffer.from(data.content, 'base64'));
        requireReceipt(!content.includes('\0'), 'binary historical engine evidence');
      }
      requireReceipt(content === source.content, 'signed engine evidence differs from the accepted engine');
      continue;
    }
    requireReceipt(safePath(source.path) && [pr.base.sha, pr.head.sha].includes(source.ref) &&
      ['source', 'contract'].includes(source.kind), 'source outside exact repository revisions');
    const contract = (source.ref === pr.base.sha || (installation && source.ref === pr.head.sha)) && [config.readme, config.repository_policy].includes(source.path);
    requireReceipt(source.authority === (contract ? 'trusted' : 'untrusted') &&
      source.kind === (contract ? 'contract' : 'source'), 'source authority was promoted');
    const sourceRepo = source.ref === pr.head.sha ? {owner: pr.head.repo.owner.login, repo: pr.head.repo.name} : repo;
    const {data} = await github.rest.repos.getContent({...sourceRepo, path: source.path, ref: source.ref});
    requireReceipt(data.encoding === 'base64' && Buffer.from(data.content, 'base64').toString('utf8') === source.content,
      'signed evidence differs from repository source');
  }
  for (const file of snapshot.files) {
    const live = files.find(item => item.filename === file.path);
    for (const side of ['base', 'head']) {
      if ((side === 'base' && file.status === 'added') || (side === 'head' && file.status === 'removed')) continue;
      const source = snapshot.sources[file[`${side}_source`]];
      requireReceipt(source && source.ref === pr[side].sha &&
        source.path === (side === 'base' ? live.previous_filename || file.path : file.path),
      'changed-file evidence omitted or substituted');
    }
  }
}

module.exports = {DOMAIN, MAX_RECEIPT_BYTES, validateTrust, reviewDecision, issueReceipt, verifySignedRecord, verifyReceipt, marker, loadReceipt, verifySources};

import assert from 'node:assert/strict';

// Consumers pass their parsed real workflow and GitHub's expression evaluator.
export function assertFrozenWorkflow(workflow, evaluate) {
  const resolver = workflow.jobs['resolve-clouseau'];
  assert.ok(resolver, 'one isolated resolver job is required');
  assert.deepEqual(resolver.permissions, {contents: 'read'});
  assert.equal(resolver.steps.length, 1);
  assert.match(resolver.steps[0].uses, /^gaulatti\/clouseau\/scripts\/resolve@[a-f0-9]{40}$/);
  assert.equal(resolver.steps[0].with, undefined, 'contributors cannot configure a source');
  assert.equal(resolver.outputs.sha, '${{ steps.engine.outputs.sha }}');
  assert.equal(resolver.outputs.digest, '${{ steps.engine.outputs.digest }}');
  const original = {sha: 'a'.repeat(40), digest: 'c'.repeat(64)};
  const next = {sha: 'b'.repeat(40), digest: 'd'.repeat(64)};
  let count = 0;
  for (const [name, job] of Object.entries(workflow.jobs)) {
    const checkouts = job.steps?.filter(step => step.with?.repository === 'gaulatti/clouseau' || step.with?.path === '.clouseau-ci') || [];
    const checkout = checkouts[0];
    const actions = job.steps?.filter(step => step.uses === './.clouseau-ci') || [];
    if (!checkout && !actions.length) continue;
    count++;
    assert.ok(checkout, name);
    assert.equal(checkouts.length, 1, `${name} cannot overwrite the frozen engine`);
    assert.equal(checkout.with.repository, 'gaulatti/clouseau', `${name} uses the authorized repository`);
    const needs = Array.isArray(job.needs) ? job.needs : [job.needs];
    assert.ok(needs.includes('resolve-clouseau'), `${name} directly consumes the one selection`);
    assert.equal(checkout.with.ref, "${{ needs.resolve-clouseau.outputs.sha || '0000000000000000000000000000000000000000' }}");
    assert.equal(checkout.with['persist-credentials'], false);
    assert.equal(checkout.with.path, '.clouseau-ci');
    assert.ok(!JSON.stringify(job).includes('gaulatti/clouseau@'), `${name} cannot mix pinned engines`);
    for (const [selected, currentMain] of [[original, next], [next, next]]) {
      const context = {needs: {'resolve-clouseau': {result: 'success', outputs: selected}},
        github: {event_name: 'pull_request_target', event: {pull_request: {body: currentMain.sha, head: {sha: currentMain.sha}}}}};
      assert.equal(evaluate(checkout.with.ref, context).coerceString(), selected.sha, name);
      assert.equal(evaluate(job.env.CLOUSEAU_ENGINE_SHA, context).coerceString(), selected.sha, name);
      assert.equal(evaluate(job.env.CLOUSEAU_ENGINE_DIGEST, context).coerceString(), selected.digest, name);
    }
    const failure = {needs: {'resolve-clouseau': {result: 'failure', outputs: {}}}, github: {event_name: 'pull_request_target'}};
    assert.equal(evaluate(checkout.with.ref, failure).coerceString(), '0'.repeat(40), `${name} has no stale fallback`);
    for (const action of actions) assert.ok(job.steps.indexOf(checkout) < job.steps.indexOf(action), name);
  }
  assert.ok(count >= 2, 'multiple engine stages must be checked');
}

'use strict';
const fs = require('node:fs');
const path = require('node:path');
const crypto = require('node:crypto');
const {digest} = require('./acceptance.cjs');

function engineDigest(root = path.join(__dirname, '..')) {
  const entries = [];
  function visit(relative) {
    const filename = path.join(root, relative);
    const stat = fs.lstatSync(filename);
    if (stat.isSymbolicLink()) throw new Error('Review engine source cannot contain symbolic links');
    if (stat.isDirectory()) {
      for (const name of fs.readdirSync(filename).sort()) {
        if (name === '__pycache__' || /\.(test|spec)\.[cm]?js$/.test(name) || /^test_.*\.py$/.test(name)) continue;
        visit(path.join(relative, name));
      }
    } else {
      entries.push([relative.split(path.sep).join('/'), stat.mode & 0o111,
        crypto.createHash('sha256').update(fs.readFileSync(filename)).digest('hex')]);
    }
  }
  for (const relative of ['action.yml', 'src', 'policy', 'bin', 'skills', 'scripts']) visit(relative);
  return digest(entries);
}
module.exports = {engineDigest};

'use strict';

const LOCATIONS = ['.github/CODEOWNERS', 'CODEOWNERS', 'docs/CODEOWNERS'];
const user = /^[a-zA-Z0-9][a-zA-Z0-9-]{0,38}$/;

function pattern(value) {
  if (!value || /[!\[\]\\\0]/.test(value) || value.includes('***')) throw new Error('Unsupported CODEOWNERS pattern; manual ownership verification required');
  const rooted = value.startsWith('/');
  const directory = value.endsWith('/');
  const input = value.replace(/^\//, '').replace(/\/$/, '');
  // https://docs.github.com/en/repositories/managing-your-repositorys-settings-and-features/customizing-your-repository/about-code-owners
  // GitHub documents docs/* as non-recursive. Other terminal prefix globs
  // may refer to directories; do not fall through to a broader owner rule.
  if (!directory && /[*?]$/.test(input) && !['*', '**'].includes(input.split('/').at(-1))) throw new Error('Ambiguous CODEOWNERS prefix glob; manual ownership verification required');
  let expression = '';
  for (let i = 0; i < input.length; i++) {
    if (input.slice(i, i + 3) === '**/') { expression += '(?:.*/)?'; i += 2; }
    else if (input.slice(i, i + 2) === '**') { expression += '.*'; i++; }
    else if (input[i] === '*') expression += '[^/]*';
    else if (input[i] === '?') expression += '[^/]';
    else expression += input[i].replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  }
  return new RegExp((rooted || input.includes('/') ? '^' : '(?:^|/)') + expression +
    (directory ? '/.*$' : /[*?]$/.test(input) ? '$' : '(?:/.*)?$'));
}

function parse(text) {
  if (typeof text !== 'string' || Buffer.byteLength(text) >= 3000000) throw new Error('CODEOWNERS is missing or oversized');
  const entries = [];
  for (const raw of text.split(/\r?\n/)) {
    const line = raw.replace(/#.*/, '').trim();
    if (!line) continue;
    const [glob, ...owners] = line.split(/\s+/);
    if (owners.some(owner => !/^@[a-zA-Z0-9][a-zA-Z0-9-]{0,38}(?:\/[a-zA-Z0-9_-]+)?$/.test(owner))) {
      throw new Error('Unverifiable CODEOWNERS identity; use GitHub usernames or teams');
    }
    entries.push({pattern: pattern(glob), owners});
  }
  return entries;
}

async function owns(github, repo, login, owners) {
  if (!user.test(login || '')) return false;
  const {data} = await github.rest.repos.getCollaboratorPermissionLevel({...repo, username: login});
  if (!['admin', 'maintain', 'write'].includes(data.permission)) return false;
  for (const owner of owners) {
    if (owner.toLowerCase() === `@${login}`.toLowerCase()) return true;
    const team = /^@([^/]+)\/(.+)$/.exec(owner);
    if (team && team[1].toLowerCase() === repo.owner.toLowerCase()) {
      const args = {org: team[1], team_slug: team[2], owner: repo.owner, repo: repo.repo};
      const {data: permission} = await github.rest.teams.checkPermissionsForRepoInOrg(args);
      if (permission.permissions?.push !== true) continue;
      const {data: membership} = await github.rest.teams.getMembershipForUserInOrg({org: team[1], team_slug: team[2], username: login});
      if (membership.state === 'active') return true;
    }
  }
  return false;
}

async function authority({github, repo, pr, files}) {
  try {
    let content;
    let location;
    for (const path of LOCATIONS) {
      try {
        const {data} = await github.rest.repos.getContent({...repo, path, ref: pr.base.sha});
        if (data.encoding !== 'base64' || typeof data.content !== 'string' || data.size >= 3000000) throw new Error('Incomplete CODEOWNERS source');
        content = new TextDecoder('utf-8', {fatal: true}).decode(Buffer.from(data.content, 'base64'));
        location = path; break;
      } catch (error) { if (error.status !== 404) throw error; }
    }
    if (content === undefined) return {automatic: true, configured: false, groups: [], base_sha: pr.base.sha,
      reason: 'No CODEOWNERS exists on the protected base; the optional code-owner gate is inactive.'};
    if (!files.length || files.length !== pr.changed_files) throw new Error('Incomplete ownership path inventory');
    const entries = parse(content);
    const paths = [...new Set(files.flatMap(file => file.previous_filename ? [file.previous_filename, file.filename] : [file.filename]))];
    const groups = paths.map(path => ({path, owners: entries.filter(entry => entry.pattern.test(path)).at(-1)?.owners || []}));
    const owner = pr.user?.type === 'User' && groups.every(group => group.owners.length);
    let automatic = Boolean(owner);
    if (automatic) for (const group of groups) if (!await owns(github, repo, pr.user.login, group.owners)) {automatic = false; break;}
    return {automatic, groups, location, base_sha: pr.base.sha,
      reason: automatic ? 'The PR author owns every affected path on the protected base.' : 'A code owner must approve this exact revision and merge manually; automatic merge is disabled.'};
  } catch (error) { return {automatic: false, groups: [], reason: `Automatic merge denied: ${error.message}`}; }
}

async function approved({github, repo, pr, ownership}) {
  if (!ownership.groups.length || ownership.groups.some(group => !group.owners.length)) return false;
  const reviews = await github.paginate(github.rest.pulls.listReviews, {...repo, pull_number: pr.number, per_page: 100});
  const latest = new Map();
  for (const review of reviews) if (review.user?.type === 'User' && review.user.login !== pr.user.login && review.state !== 'COMMENTED') latest.set(review.user.login, review);
  const accepted = [...latest.values()].filter(review => review.state === 'APPROVED' && review.commit_id === pr.head.sha);
  for (const group of ownership.groups) {
    let covered = false;
    for (const review of accepted) {
      try { if (await owns(github, repo, review.user.login, group.owners)) {covered = true; break;} } catch { /* Unverifiable membership grants no authority. */ }
    }
    if (!covered) return false;
  }
  return true;
}

module.exports = {pattern, parse, owns, authority, approved};

'use strict';

async function assertMergeProtection({github, repo, baseBranch, manual, privateOwnerAutomatic = false, assertProtection}) {
  const {data: settings} = await github.rest.repos.get(repo);
  const {data: branch} = await github.rest.repos.getBranch({...repo, branch: baseBranch});
  if (manual) {
    if (settings.allow_auto_merge !== false) throw new Error('Manual merge mode requires repository auto-merge to be disabled');
    try {
      await assertProtection();
    } catch (error) {
      if (!(settings.private === true && branch.protected === false && error.status === 403 &&
          /Upgrade to GitHub Pro or make this repository public/i.test(error.message))) throw error;
      return {enforced: false, reason: 'GitHub cannot enforce protection on this private plan. Tests and review passed independently; every merge remains manual.'};
    }
    if (branch.protected !== true) throw new Error('Available branch protection must be enabled before manual-mode approval');
    return {enforced: true};
  }
  if (privateOwnerAutomatic && settings.private === true && branch.protected === false && settings.allow_auto_merge === false) {
    try { await assertProtection(); } catch (error) {
      if (!(error.status === 403 && /Upgrade to GitHub Pro or make this repository public/i.test(error.message))) throw error;
      return {enforced: false, controllerManaged: true, reason: 'Private-plan branch protection is unavailable; explicit code-owner work alone may use the controller-enforced atomic acceptance path.'};
    }
    throw new Error('Available branch protection must be enabled before automatic approval');
  }
  if (!settings.allow_auto_merge || !branch.protected) throw new Error('Repository auto-merge and main protection must be enabled');
  await assertProtection();
  return {enforced: true};
}

module.exports = {assertMergeProtection};

'use strict';

// An exact-head/base transaction for the narrow private-plan exception only.
// Callers must first validate the acceptance record and all technical gates.
async function finalizePrivateOwner({github, repo, pr, assessment, baseBranch, verify}) {
  const exact = value => value.state === 'open' && !value.draft &&
    value.head.sha === assessment.head_sha && value.base.sha === assessment.base_sha && value.base.ref === baseBranch;
  if (!exact(pr) || !/^[a-f0-9]{40}$/.test(assessment.head_sha) || !/^[a-f0-9]{40}$/.test(assessment.base_sha)) {
    throw new Error('Private owner merge requires the exact open assessed head and base');
  }
  const {data: settings} = await github.rest.repos.get(repo);
  const safeRef = ref => typeof ref === 'string' && /^[A-Za-z0-9_][A-Za-z0-9_./-]*$/.test(ref) &&
    !ref.includes('..') && !ref.includes('//') && !ref.endsWith('/') && !ref.endsWith('.lock');
  if (!settings.node_id || pr.head.repo?.node_id !== settings.node_id || pr.base.repo?.node_id !== settings.node_id ||
      !safeRef(pr.head.ref) || !safeRef(baseBranch) || pr.head.ref === baseBranch || pr.auto_merge) {
    throw new Error('Private owner merge requires distinct same-repository refs and disabled native auto-merge');
  }
  const files = await github.paginate(github.rest.pulls.listFiles, {...repo, pull_number: pr.number, per_page: 100});
  const authority = await require('./codeowners.cjs').authority({github, repo, pr, files});
  if (!authority.automatic || authority.configured === false || !authority.groups.length) {
    throw new Error('Private automatic merge requires explicitly configured ownership of every affected path');
  }
  const reviews = await github.paginate(github.rest.pulls.listReviews, {...repo, pull_number: pr.number, per_page: 100});
  const latest = new Map();
  for (const review of reviews) if (review.state !== 'COMMENTED') latest.set(review.user?.login, review);
  const approval = latest.get('github-actions[bot]');
  if (!approval || approval.user.type !== 'Bot' || approval.state !== 'APPROVED' || approval.commit_id !== assessment.head_sha ||
      [...latest.values()].some(review => review.user?.type === 'User' && review.state === 'CHANGES_REQUESTED')) {
    throw new Error('Private automatic merge requires a fresh current-head bot approval and no outstanding change requests');
  }
  const {data: comparison} = await github.rest.repos.compareCommits({...repo, base: assessment.base_sha, head: assessment.head_sha});
  if (comparison.status !== 'ahead' || comparison.merge_base_commit?.sha !== assessment.base_sha) {
    throw new Error('Private owner merge requires the exact accepted base to be an ancestor of the reviewed head');
  }
  await verify();
  const {data: current} = await github.rest.pulls.get({...repo, pull_number: pr.number});
  const {data: branch} = await github.rest.repos.getBranch({...repo, branch: baseBranch});
  if (!exact(current) || current.auto_merge || branch.commit.sha !== assessment.base_sha || branch.protected !== false) {
    throw new Error('Private owner merge head, base or protection changed before the atomic write');
  }
  await github.graphql(`mutation($input:UpdateRefsInput!) { updateRefs(input:$input) { clientMutationId } }`, {input: {
    repositoryId: settings.node_id,
    refUpdates: [
      {name: `refs/heads/${baseBranch}`, beforeOid: assessment.base_sha, afterOid: assessment.head_sha, force: false},
      {name: `refs/heads/${pr.head.ref}`, beforeOid: assessment.head_sha, afterOid: assessment.head_sha, force: false},
    ],
  }});
  const {data: merged} = await github.rest.pulls.get({...repo, pull_number: pr.number});
  const {data: mergedBase} = await github.rest.repos.getBranch({...repo, branch: baseBranch});
  if (!merged.merged || merged.head?.sha !== assessment.head_sha || merged.merge_commit_sha !== assessment.head_sha || mergedBase.commit.sha !== assessment.head_sha) {
    throw new Error('Atomic owner merge submitted but exact merged PR audit is not yet observable; inspect before retrying');
  }
  return merged;
}

module.exports = {finalizePrivateOwner};

